SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷76·晋高祖纪·天福二年六月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c90e9012/content/books/zizhi-tongjian/vol-281/year-0937/part-04/sources/library/jiuwudaishi-076-937-june/source.txt", "note": "《旧五代史》卷76·晋高祖纪·天福二年六月，段落 jiu-wudaishi-205deb4a7860-p001901；已核上下文及传主，纸本及异文待核。", "id": "51b86c68-aa1c-5163-9565-3b9a2b8dbbf5"}, {"title": "旧五代史·卷76·晋高祖纪·天福二年八月追记李遐遇害", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c90e9012/content/books/zizhi-tongjian/vol-281/year-0937/part-04/sources/library/jiuwudaishi-076-li-xia-background/source.txt", "note": "《旧五代史》卷76·晋高祖纪·天福二年八月追记李遐遇害，段落 jiu-wudaishi-205deb4a7860-p001904；已核上下文及传主，纸本及异文待核。", "id": "bc994d7c-74ed-5051-b774-a0c7a36f5238"}, {"title": "旧五代史·卷109·杜重威传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c90e9012/content/books/zizhi-tongjian/vol-281/year-0937/part-04/sources/library/jiuwudaishi-109-du-chongwei/source.txt", "note": "《旧五代史》卷109·杜重威传，段落 jiu-wudaishi-205deb4a7860-p002616；已核上下文及传主，纸本及异文待核。", "id": "05b53010-8015-5b47-aa3d-91b2b2cf7ec4"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c90e9012/content/books/zizhi-tongjian/vol-281/year-0937/part-04/sources/library/tongjian-281-937-rebellion/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003341；电子底本待考，分段待核", "id": "e84d096f-85d1-5bb4-8532-79f46629b49b"}, {"title": "新五代史·卷51·范延光传", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c90e9012/content/books/zizhi-tongjian/vol-281/year-0937/part-04/sources/library/xinwudaishi-051-fan-rebellion/source.txt", "note": "《新五代史》卷51·范延光传，段落 xin-wudaishi-b08f244b9241-p001987；已核上下文及传主，纸本及异文待核。", "id": "e90f4ec6-7f7f-56d2-8e3b-956335e02629"}, {"title": "新五代史·卷68·闽世家", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c90e9012/content/books/zizhi-tongjian/vol-281/year-0937/part-04/sources/library/xinwudaishi-068-chen-jiu/source.txt", "note": "《新五代史》卷68·闽世家，段落 xin-wudaishi-b08f244b9241-p003404；已核上下文及传主，纸本及异文待核。", "id": "d174fe35-0b78-5ef1-9029-944006402f6d"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7d3fe25/content/books/zizhi-tongjian/vol-281/year-0937/part-02/sources/library/tongjian-281-937-wuyue/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003340；电子底本待考，分段待核", "id": "23fb5d4f-058c-57b4-8203-01b3b99c9157"}, {"title": "旧五代史·卷95·吴峦传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7d3fe25/content/books/zizhi-tongjian/vol-281/year-0937/part-02/sources/library/jiuwudaishi-095-wu-luan/source.txt", "note": "《旧五代史》卷95·吴峦传，段落 jiu-wudaishi-205deb4a7860-p002322；已核上下文及传主，纸本及异文待核。", "id": "cf096879-1d45-5ffc-b500-2836fb5cbbd6"}, {"title": "新五代史·卷29·吴峦传", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a7d3fe25/content/books/zizhi-tongjian/vol-281/year-0937/part-02/sources/library/xinwudaishi-029-wu-luan/source.txt", "note": "《新五代史》卷29·吴峦传，段落 xin-wudaishi-b08f244b9241-p001074；已核上下文及传主，纸本及异文待核。", "id": "63f87883-b1ec-5403-b556-43c9535a0aed"}]'::jsonb)
