INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "孙锐", "aliases": ["孫銳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范延光的元随左都押牙。范延光把军府事务交给他处理。937年与冯晖共同劝逼范延光起兵，随后担任兵马都监。", "biography": null, "status": "draft", "id": "03455fb4-2e7f-5785-8536-8eb1c52c226a"}, {"name": "冯晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：冯晖。", "biography": null, "status": "draft", "id": "e59e2b00-2873-5968-ab4c-938628164ecf"}, {"name": "张言", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋六宅使。937年出使魏州返回，向石敬瑭报告范延光反叛。", "biography": null, "status": "draft", "id": "2597b88d-5084-5b49-9c34-af461691ae53"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "符彦饶", "aliases": ["符彥饒", "李彦饶", "李彥饒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦饶，被逼为帅、要求停止焚掠者。", "biography": null, "status": "draft", "id": "fab16ea8-291a-5d04-86b9-d463c9d60303"}, {"name": "白奉进", "aliases": ["白奉進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，后晋将领。937年以侍卫马军都指挥使、昭信节度使身份，奉命率一千五百骑兵驻守白马津。", "biography": null, "status": "draft", "id": "7ff1aba2-0da0-5683-8991-bd1b69aa366d"}, {"name": "张从宾", "aliases": ["張從賓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张从宾，侍卫步军都指挥使、忠正节度使。", "biography": null, "status": "draft", "id": "9a3c8e19-d709-5a20-b9dd-ef00849d161d"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "乐平长公主（杜重威妻）", "aliases": ["乐平长公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的妹妹、杜重威的妻子。937年的记载称她为乐平长公主。", "biography": null, "status": "draft", "id": "7cf58667-5bd6-58c5-8ebe-c3c1d463a473"}, {"name": "和凝", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：和凝，翰林学士、建议者。", "biography": null, "status": "draft", "id": "f4084e8d-6018-5318-8498-525d067ebeda"}, {"name": "张谊", "aliases": ["張誼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "襄邑人，曾任耀州团练推官。937年致书和凝，劝他接待宾客以了解各地情况，随后经推荐被任命为左拾遗。", "biography": null, "status": "draft", "id": "295f4205-8a74-52af-b2b9-3da930f2c475"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "吴峦", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "大同军节度判官。沙彦珣被契丹扣留后，他被推举主持云州事务，并闭城拒守。", "biography": null, "status": "draft", "id": "10e5964b-74c7-5654-afc1-4dfbc96d27c3"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "翟璋", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "威塞节度使。契丹要求他在新州筹集十万缗犒军钱。", "biography": null, "status": "draft", "id": "96b2e88f-4bbd-5920-8f6b-082ca154a484"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "石重信", "aliases": ["重信"], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "石敬瑭的儿子，任河阳节度使。937年张从宾反叛时被杀。", "biography": null, "status": "draft", "id": "1b5399d5-bbfa-5e8e-a208-e4ea88123d64"}, {"name": "张继祚", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：张继祚。", "biography": null, "status": "draft", "id": "901ce89b-5d00-51b8-8cef-3f5ea0bc8684"}, {"name": "张全义", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加封钱镠、张全义、刘隐等”中为受封者。", "biography": null, "status": "draft", "id": "3d89e670-5812-57eb-a061-8aaea77bd5e8"}, {"name": "石重乂", "aliases": ["重乂"], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "石敬瑭的儿子，代理东都留守。937年张从宾进入洛阳时被杀。", "biography": null, "status": "draft", "id": "c97e8f4a-7aae-58bb-9ee6-971cbad71593"}, {"name": "张延播", "aliases": ["張延播"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员，任东都副留守、都巡检使。937年张从宾反叛后让他主持河南府事务。", "biography": null, "status": "draft", "id": "16d3d321-f393-528d-bc49-1f9ba0e819e0"}, {"name": "李遐", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "后晋东都留守判官。937年拒绝把库中的钱帛交给张从宾的叛军，遭军士杀害。", "biography": null, "status": "draft", "id": "d77aa03f-04f4-5a4e-9948-d7424b00fcbd"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "刘处让", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘处让。", "biography": null, "status": "draft", "id": "7607f037-c9b6-5f79-b064-81fcfd4ee40d"}, {"name": "王继鹏", "aliases": ["王繼鵬", "王昶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继鹏，被任命权军府事的王子。", "biography": null, "status": "draft", "id": "94e0308c-1642-5beb-9233-76f848fff4f0"}, {"name": "蔡守蒙", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，任吏部侍郎并负责三司事务。937年在王继鹏逼迫下接受收取贿赂、登记上缴的任官办法。史书称他是候官人，地名写法待核。", "biography": null, "status": "draft", "id": "e782fe72-eb5f-5d36-b118-9f9622a67a46"}, {"name": "陈究", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国医工。937年奉王继鹏命，持未填官员姓名的任官文书到外地卖官。", "biography": null, "status": "draft", "id": "8c7da22f-bbe1-5571-a221-4f5085aeb302"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

