2702033af356"}, {"title": "桑维翰从容安排军事，史书记载官员因此稍感安定", "start_year": 937, "end_year": 937, "time_original": "937年六月，具体日期未记载", "dynasty": "五代十国", "description": "军情文书不断往来，留在大梁的随行官员惊惧。史书记载桑维翰从容安排军事，照常接待宾客，众人因而稍感安定。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "26df9817-f5e6-57cd-9e9e-e269a0dd718e"}, {"title": "王继鹏听方士称螺峰出现白龙，修建白龙寺", "start_year": 937, "end_year": 937, "time_original": "937年六月，具体日期未记载", "dynasty": "五代十国", "description": "方士向王继鹏声称螺峰夜里出现白龙，王继鹏据此修建白龙寺。", "phases": [], "location_name": "螺峰、白龙寺", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "583ec869-4413-503d-b8d2-7e192b03ca36"}, {"title": "王继鹏命蔡守蒙收取任官贿赂并登记上缴", "start_year": 937, "end_year": 937, "time_original": "937年六月，具体日期未记载", "dynasty": "五代十国", "description": "工程众多、费用不足。王继鹏询问蔡守蒙官员任命中是否有受贿现象，蔡守蒙说传言不足信。王继鹏称自己早已知情，命蔡守蒙在选贤任官之外，对不称职或冒名求官者也不要拒绝，只须收取贿赂、登记上缴。", "phases": [], "location_name": "闽", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fd4e33ea-915c-5504-a00d-7a705d2d3ccd"}, {"title": "蔡守蒙反对收贿任官，因王继鹏发怒而接受", "start_year": 937, "end_year": 937, "time_original": "937年六月，具体日期未记载", "dynasty": "五代十国", "description": "蔡守蒙反对收贿任官，因王继鹏发怒而接受。", "phases": [], "location_name": "闽", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a4587299-9653-55c5-ba48-531ee6a1907e"}, {"title": "史书记载闽国此后任官只按贿赂多少定高下", "start_year": 937, "end_year": 937, "time_original": "937年六月，具体日期未记载", "dynasty": "五代十国", "description": "史书记载闽国此后任官只按贿赂多少定高下。", "phases": [], "location_name": "闽", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1f481989-c82b-5e67-8c26-fa5a21525b0a"}, {"title": "王继鹏派医工陈究持空白任官文书到外地卖官", "start_year": 937, "end_year": 937, "time_original": "937年六月，具体日期未记载", "dynasty": "五代十国", "description": "王继鹏把未填官员姓名的任官文书交给医工陈究，让他到外地卖官。史书记载王继鹏不断聚敛财富，没有满足。", "phases": [], "location_name": "闽各地", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "aae91026-e8e8-5c05-965f-54b73f0a6d8a"}, {"title": "王继鹏下令重罚隐瞒年龄、人口和逃亡的民众", "start_year": 937, "end_year": 937, "time_original": "937年六月，具体日期未记载", "dynasty": "五代十国", "description": "王继鹏下令：隐瞒年龄者杖打背部，隐瞒人口者处死，逃亡者连同族人处死。", "phases": [], "location_name": "闽", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9d89586c-c66e-516f-bfda-4fa3fbf40d29"}, {"title": "闽国对果菜和鸡猪等征收重税", "start_year": 937, "end_year": 937, "time_original": "937年六月，具体日期未记载", "dynasty": "五代十国", "description": "闽国对果菜和鸡猪等征收重税。", "phases": [], "location_name": "闽", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b055c5b5-4d00-53dc-8802-08563d293138"}]'::jsonb)
